package com.hms.branches;
import com.hms.tenancy.*; import com.hms.billing.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/branches") public class BranchController {private final TenantRepository tenants;private final HospitalBranchRepository branches;private final PlanLimitService planLimits;public BranchController(TenantRepository t,HospitalBranchRepository b,PlanLimitService p){tenants=t;branches=b;planLimits=p;} @GetMapping public List<HospitalBranch> list(@PathVariable String tenantSlug){return branches.findAllByTenantIdOrderByNameAsc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public HospitalBranch create(@PathVariable String tenantSlug,@Valid @RequestBody CreateBranchRequest r){UUID t=tenant(tenantSlug);planLimits.checkBranch(t);return branches.save(new HospitalBranch(t,r));} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
